from __future__ import annotations

from typing import Any, cast

from django.test import override_settings
from requests import Session

from family_agent.ucp_client import UCPCatalogClient


class _FakeResponse:
    def __init__(self, payload: dict[str, Any], *, status_code: int = 200) -> None:
        self._payload = payload
        self.status_code = status_code

    def json(self) -> dict[str, Any]:
        return self._payload


@override_settings(
    FAMILY_AGENT_UCP_PLATFORM_PROFILE_URL="https://clancal.example.com/.well-known/ucp"
)
def test_search_catalog_discovers_rest_endpoint_and_normalizes_products(monkeypatch):
    captured_profile_request: dict[str, Any] = {}

    def fake_safe_get(url: str, **kwargs: Any) -> _FakeResponse:
        captured_profile_request["url"] = url
        captured_profile_request["kwargs"] = kwargs
        return _FakeResponse(
            {
                "ucp": {
                    "services": {
                        "dev.ucp.shopping": [
                            {
                                "rest": {
                                    "endpoint": "https://catalog.example.com/api",
                                }
                            }
                        ]
                    },
                    "capabilities": {
                        "dev.ucp.shopping.catalog.search": [{}],
                    },
                }
            }
        )

    class FakeSession:
        def __init__(self) -> None:
            self.calls: list[dict[str, Any]] = []

        def post(self, url: str, **kwargs: Any) -> _FakeResponse:
            self.calls.append({"url": url, "kwargs": kwargs})
            return _FakeResponse(
                {
                    "products": [
                        {
                            "id": "prod-throw-1",
                            "title": "Organic Cotton Throw Blanket",
                            "description": {
                                "plain_text": "Soft neutral blanket for guest rooms.",
                            },
                            "categories": [{"label": "Home"}],
                            "media": [
                                {
                                    "url": "https://cdn.example.com/product.jpg",
                                    "alt_text": "Folded throw blanket",
                                }
                            ],
                            "variants": [
                                {
                                    "id": "variant-cream-queen",
                                    "title": "Cream / Queen",
                                    "url": "https://shop.example.com/products/throw?variant=cream-queen",
                                    "price": {"amount": 12900, "currency": "USD"},
                                    "list_price": {
                                        "amount": 14900,
                                        "currency": "USD",
                                    },
                                    "availability": {"label": "In stock"},
                                    "seller": {"name": "Example Shop"},
                                    "media": [
                                        {
                                            "url": "https://cdn.example.com/variant.jpg",
                                            "alt_text": "Cream throw blanket on a bed",
                                        }
                                    ],
                                }
                            ],
                        }
                    ],
                    "pagination": {"cursor": "next-page"},
                    "messages": ["Fresh catalog sync"],
                }
            )

    fake_session = FakeSession()
    monkeypatch.setattr("family_agent.ucp_client.safe_get", fake_safe_get)

    client = UCPCatalogClient(session=cast(Session, fake_session))
    result = client.search_catalog(
        merchant_domain="shop.example.com",
        query="throw blanket",
        categories=["home"],
        min_price_minor=10000,
        max_price_minor=15000,
        currency="usd",
        intent="gift",
        limit=3,
    )

    assert captured_profile_request["url"] == "https://shop.example.com/.well-known/ucp"
    assert captured_profile_request["kwargs"]["headers"]["UCP-Agent"] == (
        'profile="https://clancal.example.com/.well-known/ucp"'
    )

    post_call = fake_session.calls[0]
    assert post_call["url"] == "https://catalog.example.com/api/catalog/search"
    assert post_call["kwargs"]["json"] == {
        "query": "throw blanket",
        "context": {
            "currency": "USD",
            "intent": "gift",
        },
        "filters": {
            "categories": ["home"],
            "price": {
                "min": 10000,
                "max": 15000,
            },
        },
        "pagination": {"limit": 3},
    }
    assert post_call["kwargs"]["headers"]["UCP-Agent"] == (
        'profile="https://clancal.example.com/.well-known/ucp"'
    )

    assert result == {
        "ok": True,
        "merchant_domain": "shop.example.com",
        "profile_url": "https://shop.example.com/.well-known/ucp",
        "service_endpoint": "https://catalog.example.com/api",
        "products": [
            {
                "id": "prod-throw-1",
                "title": "Organic Cotton Throw Blanket",
                "url": "https://shop.example.com/products/throw?variant=cream-queen",
                "description": "Soft neutral blanket for guest rooms.",
                "merchant_name": "Example Shop",
                "merchant_domain": "shop.example.com",
                "image_url": "https://cdn.example.com/variant.jpg",
                "image_alt": "Cream throw blanket on a bed",
                "variant_id": "variant-cream-queen",
                "variant_title": "Cream / Queen",
