from __future__ import annotations

from collections import defaultdict
from collections.abc import Iterable
from typing import Any, cast

from django.db.models import Prefetch, QuerySet
from rest_framework.request import Request

from family_scheduler.utils.observability import child_span, set_span_attributes
from users.utils import _build_external_calendar_lookup, build_calendar_lookup_dicts

from .arrive_by import can_user_view_arrive_by
from .models import (
    Event,
    EventFamilyGroups,
    EventMedia,
    EventParticipant,
    EventReminder,
)
from .sharing_models import TentativeEventShare
from .weather_models import EventWeatherSnapshot


def _event_family_participation_queryset() -> QuerySet[EventFamilyGroups]:
    return EventFamilyGroups.objects.select_related(
        "familygroup",
        "familygroup__group_type",
        "familygroup__feature_settings",
        "invited_by",
        "inviting_group",
        "source_group",
        "source_group__group_type",
    ).prefetch_related(
        "familygroup__memberships__user",
        "familygroup__party_units__represented_members",
    )


def _attach_confirmed_event_read_collections(
    *,
    events: list[Event],
    user: Any,
) -> None:
    confirmed_event_ids = [
        event.id for event in events if event.event_status == Event.STATUS_CONFIRMED
    ]
    if not confirmed_event_ids:
        return

    participations_by_event: dict[Any, list[EventFamilyGroups]] = defaultdict(list)
    for participation in _event_family_participation_queryset().filter(
        event_id__in=confirmed_event_ids
    ):
        participations_by_event[participation.event_id].append(participation)

    viewer_participants_by_event: dict[Any, list[EventParticipant]] = defaultdict(list)
    if getattr(user, "is_authenticated", False):
        for participant in EventParticipant.objects.filter(
            user=user,
            event_id__in=confirmed_event_ids,
        ):
            viewer_participants_by_event[participant.event_id].append(participant)

    for event in events:
        if event.event_status != Event.STATUS_CONFIRMED:
            continue
        object.__setattr__(
            event,
            "_prefetched_family_participations",
            participations_by_event.get(event.id, []),
        )
        object.__setattr__(
            event,
            "_viewer_participants",
            viewer_participants_by_event.get(event.id, []),
        )


def optimize_event_queryset_for_read(
    queryset: QuerySet[Event],
    *,
    user: Any,
    include_media: bool,
) -> QuerySet[Event]:
    queryset = queryset.select_related(
        "creator",
        "creator__profile",
        "assigned_user",
        "assigned_user__profile",
        "assigned_child",
        "family_group",
        "family_group__group_type",
        "internal_calendar",
        "internal_calendar__user",
        "internal_calendar__user__profile",
        "source_group_plan",
        "source_group_plan__family_group",
        "source_group_plan__family_group__group_type",
    ).prefetch_related(
        "creator__socialaccount_set",
        "creator__child_profile",
        "assigned_user__socialaccount_set",
        "assigned_user__child_profile",
        "internal_calendar__associated_users__profile",
        "internal_calendar__associated_users__child_profile",
        "internal_calendar__associated_users__socialaccount_set",
        "internal_calendar__associated_children",
    )

    if include_media:
        media_queryset = cast(
            Any,
            EventMedia.objects.select_related("uploaded_by__profile"),
        ).prefetch_related("tags")
        queryset = queryset.prefetch_related(
            Prefetch(
                "media",
                queryset=media_queryset,
            )
        )

    if getattr(user, "is_authenticated", False):
        queryset = queryset.prefetch_related(
            Prefetch(
                "reminders",
                queryset=EventReminder.objects.filter(user=user),
                to_attr="_current_user_reminders",
            ),
        )

    return queryset


def build_event_read_serializer_context(
    *,
    request: Request,
    events: Iterable[Event],
    base_context: dict[str, Any] | None = None,
) -> dict[str, Any]:
    context = dict(base_context or {})
    event_list = list(events)
    user = getattr(request, "user", None)

    context["prefetched_events"] = event_list
    context["external_calendars_dict"] = {}
    context["external_calendar_lookup"] = {}
    context["internal_calendars_dict"] = {}
    context["user_reminders_map"] = {}
    context["tentative_share_map"] = {}
    context["arrive_by_visibility_map"] = {}
    context["weather_snapshot_map"] = {}
    context["viewer_direct_family_ids"] = set()

    if not event_list or not getattr(user, "is_authenticated", False):
        return context

    authenticated_user = cast(Any, user)
    viewer_direct_family_ids = set(
        authenticated_user.family_memberships.filter(is_active=True).values_list(
            "family_id", flat=True
        )
    )
    context["viewer_direct_family_ids"] = viewer_direct_family_ids
    context["arrive_by_visibility_map"] = {
        str(event.id): can_user_view_arrive_by(
            event,
            authenticated_user,
            direct_family_ids=viewer_direct_family_ids,
        )
        for event in event_list
    }

    family_ids = [
        event.family_group_id
        for event in event_list
        if event.family_group_id is not None
    ]
    with child_span("api.events.context.build_calendar_lookups") as lookup_span:
        external_cals, internal_cals = build_calendar_lookup_dicts(
            event_list,
            authenticated_user,
            family_ids=family_ids,
        )
        external_lookup = _build_external_calendar_lookup(external_cals)
        context["external_calendars_dict"] = external_cals
        context["external_calendar_lookup"] = external_lookup
        context["internal_calendars_dict"] = internal_cals
        set_span_attributes(
            lookup_span,
            event_count=len(event_list),
            external_calendar_count=len(
                {calendar.id for calendar in external_cals.values()}
            ),
            internal_calendar_count=len(internal_cals),
        )

    with child_span(
        "api.events.context.attach_confirmed_participations"
    ) as participation_span:
        _attach_confirmed_event_read_collections(
            events=event_list,
            user=authenticated_user,
        )
        set_span_attributes(
            participation_span,
            confirmed_event_count=sum(
                1
                for event in event_list
                if event.event_status == Event.STATUS_CONFIRMED
            ),
        )

    with child_span("api.events.context.build_reminder_map") as reminder_span:
        reminder_map: dict[str, EventReminder | None] = {
            str(event.id): None for event in event_list
        }
        prefetched_reminders = True
        for event in event_list:
            if hasattr(event, "_current_user_reminders"):
                prefetched_event_reminders = list(event._current_user_reminders)
                if prefetched_event_reminders:
                    reminder_map[str(event.id)] = prefetched_event_reminders[0]
            else:
                prefetched_reminders = False

        if not prefetched_reminders:
            reminder_queryset = EventReminder.objects.filter(
                user=authenticated_user,
                event_id__in=[event.id for event in event_list],
            )
            for reminder in reminder_queryset:
                reminder_map[str(reminder.event_id)] = reminder

        context["user_reminders_map"] = reminder_map
        set_span_attributes(
            reminder_span,
            prefetched_reminders=prefetched_reminders,
            populated_reminder_count=sum(
                1 for reminder in reminder_map.values() if reminder is not None
            ),
        )

    with child_span("api.events.context.build_weather_snapshot_map") as weather_span:
        snapshots = EventWeatherSnapshot.objects.filter(
            event_id__in=[event.id for event in event_list]
        )
        context["weather_snapshot_map"] = {
            str(snapshot.event_id): snapshot for snapshot in snapshots
        }
        set_span_attributes(
            weather_span,
            weather_snapshot_count=len(context["weather_snapshot_map"]),
        )

    tentative_event_ids = [
        event.id for event in event_list if event.event_status == Event.STATUS_TENTATIVE
    ]
    with child_span("api.events.context.build_tentative_share_map") as share_span:
        if tentative_event_ids:
            cached_family_ids = getattr(request, "_event_access_family_ids", None)
            user_family_ids = (
                list(cached_family_ids)
                if cached_family_ids is not None
                else list(
                    authenticated_user.family_memberships.values_list(
                        "family_id", flat=True
                    )
                )
            )
            shares = (
                TentativeEventShare.objects.filter(
                    event_id__in=tentative_event_ids,
                    target_family_id__in=user_family_ids,
                )
                .select_related("source_family")
                .order_by("created_at")
            )
            context["tentative_share_map"] = {
                str(share.event_id): share for share in shares
            }
        set_span_attributes(
            share_span,
            tentative_event_count=len(tentative_event_ids),
            shared_tentative_count=len(context["tentative_share_map"]),
        )

    return context

