def sync_region_event_mirror(region_event: RegionEvent) -> Event | None:
    """Create or update the mirrored Event row for a RegionEvent when possible."""

    region_calendar = region_event.region_calendar
    if region_calendar is None:
        logger.warning(
            "RegionEvent %s has no region_calendar, skipping sync",
            region_event.id,
        )
        return None

    if region_calendar.internal_calendar is None:
        logger.warning(
            "RegionCalendar %s has no internal_calendar, skipping sync",
            region_calendar.id,
        )
        return None

    event_data = {
        "title": region_event.name,
        "description": region_event.description,
        "start_time": region_event.start_datetime,
        "end_time": region_event.end_datetime,
        "location": region_event.location,
        "internal_calendar": region_calendar.internal_calendar,
        "creator": region_event.created_by,
        "visibility": "PUBLIC",
        "is_regional_event_mirror": True,
    }

    mirrored_event, _ = Event.objects.update_or_create(
        mirrored_region_event=region_event,
        defaults=event_data,
    )
    return mirrored_event


def resync_region_calendar_events(region_calendar: RegionCalendar) -> int:
    """Rebuild mirrored Event rows for every RegionEvent on the calendar."""

    mirrored_event_count = 0
    region_events = region_calendar.events.select_related(
        "region_calendar__internal_calendar"
    )
    for region_event in region_events:
        if sync_region_event_mirror(region_event) is not None:
            mirrored_event_count += 1
    return mirrored_event_count


