class EventMediaSerializer(serializers.ModelSerializer[EventMedia]):
    """Serializer for event media"""

    presigned_url = serializers.SerializerMethodField()
    uploaded_by_name = serializers.SerializerMethodField()

    class Meta:
        model = EventMedia
        fields = [
            "id",
            "event",
            "uploaded_by",
            "uploaded_by_name",
            "media_type",
            "original_filename",
            "caption",
            "uploaded_at",
            "file_size",
            "content_type",
            "presigned_url",
        ]
        read_only_fields = [
            "id",
            "event",
            "uploaded_by",
            "media_type",
            "original_filename",
            "uploaded_at",
            "file_size",
            "content_type",
            "presigned_url",
        ]

    def get_presigned_url(self, obj: EventMedia) -> str | None:
        """Generate a presigned URL for the media file"""
        # It's generally better practice to import services at the top level,
        # but keeping it here if it was done for a specific reason (e.g., avoid circular imports with services)
        from .services import MediaStorageService

        request_host = _request_host_from_context(self.context)

        # Add error handling in case the service or key is unavailable
        try:
            return MediaStorageService.generate_presigned_url(
                obj.file_key,
                request_host=request_host,
            )
        except Exception as e:
            # Log the error appropriately in a real application
            logger.error(
                "Error generating presigned URL for key %s: %s", obj.file_key, e
            )
            return None

    def get_uploaded_by_name(self, obj: EventMedia) -> str:
        """Get the name of the user who uploaded the file"""
        # Add safety check for obj.uploaded_by
        if obj.uploaded_by:
            return obj.uploaded_by.get_full_name() or obj.uploaded_by.username
        return "Unknown User"


